CREATE OR REPLACE FUNCTION public.resolve_contact_identity(p_organization_id uuid, p_email text, p_full_name text, p_company_id uuid DEFAULT NULL::uuid, p_owner_user_id uuid DEFAULT NULL::uuid, p_role_title text DEFAULT NULL::text, p_source text DEFAULT 'unknown'::text, p_create_if_missing boolean DEFAULT true)
 RETURNS TABLE(contact_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare
  normalized_email_value text := public.normalize_identity_email(p_email);
  normalized_name_value text := public.normalize_entity_name(p_full_name);
  resolved_id uuid;
begin
  if auth.role() <> 'service_role' and not private.is_org_member(p_organization_id) then
    raise exception 'Accès refusé';
  end if;
  if normalized_email_value is null and normalized_name_value is null then
    raise exception 'Un email ou un nom est nécessaire pour résoudre une personne';
  end if;

  if normalized_email_value is not null
     and private.is_org_member_email(p_organization_id, normalized_email_value) then
    return;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || '|contact|' ||
    coalesce(normalized_email_value, normalized_name_value || '|' || coalesce(p_company_id::text, 'sans-compte')),
    0
  ));

  if normalized_email_value is not null then
    select alias.contact_id into resolved_id
    from public.contact_identity_aliases alias
    join public.contacts contact on contact.id = alias.contact_id
    where alias.organization_id = p_organization_id
      and alias.identity_type = 'email'
      and alias.identity_value = normalized_email_value
      and contact.merged_into_contact_id is null
    limit 1;
  end if;

  if resolved_id is null and normalized_email_value is not null then
    select id into resolved_id
    from public.contacts
    where organization_id = p_organization_id
      and merged_into_contact_id is null
      and (
        public.normalize_identity_email(email) = normalized_email_value
        or exists (
          select 1 from unnest(coalesce(secondary_emails, array[]::text[])) secondary
          where public.normalize_identity_email(secondary) = normalized_email_value
        )
      )
    order by created_at
    limit 1;
  end if;

  if resolved_id is null and normalized_email_value is null then
    select id into resolved_id
    from public.contacts
    where organization_id = p_organization_id
      and merged_into_contact_id is null
      and public.normalize_entity_name(full_name) = normalized_name_value
      and company_id is not distinct from p_company_id
    order by created_at
    limit 1;
  end if;

  if resolved_id is not null then
    update public.contacts
    set full_name = case
          when full_name = split_part(email, '@', 1)
            or length(full_name) < length(coalesce(nullif(btrim(p_full_name), ''), full_name))
          then coalesce(nullif(btrim(p_full_name), ''), full_name)
          else full_name
        end,
        company_id = coalesce(company_id, p_company_id),
        owner_user_id = coalesce(owner_user_id, p_owner_user_id),
        role_title = coalesce(role_title, nullif(btrim(p_role_title), '')),
        source_summary = coalesce(source_summary, '{}'::jsonb)
          || jsonb_build_object('last_identity_source', p_source, 'last_identity_seen_at', now()),
        updated_at = now()
    where id = resolved_id;

    if normalized_email_value is not null then
      insert into public.contact_identity_aliases (
        organization_id, contact_id, identity_type, identity_value, source
      )
      values (
        p_organization_id, resolved_id, 'email', normalized_email_value, p_source
      )
      on conflict (organization_id, identity_type, identity_value) do update
      set contact_id = excluded.contact_id,
          source = excluded.source,
          last_seen_at = now();
    end if;

    return query select resolved_id, false;
    return;
  end if;

  if not p_create_if_missing then
    return;
  end if;

  insert into public.contacts (
    organization_id,
    company_id,
    owner_user_id,
    full_name,
    email,
    role_title,
    source_summary
  )
  values (
    p_organization_id,
    p_company_id,
    p_owner_user_id,
    coalesce(nullif(btrim(p_full_name), ''), split_part(coalesce(normalized_email_value, ''), '@', 1), 'Contact'),
    normalized_email_value,
    nullif(btrim(p_role_title), ''),
    jsonb_build_object('source', p_source, 'discovered_from', p_source)
  )
  returning id into resolved_id;

  if normalized_email_value is not null then
    insert into public.contact_identity_aliases (
      organization_id, contact_id, identity_type, identity_value, source
    )
    values (
      p_organization_id, resolved_id, 'email', normalized_email_value, p_source
    );
  end if;

  return query select resolved_id, true;
end;
$function$

CREATE OR REPLACE FUNCTION public.acquire_enrichment_slot()
 RETURNS smallint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id smallint;
begin
  select id into v_id
  from public.enrichment_slots
  where locked_at is null or locked_at < now() - interval '5 minutes'
  order by id
  limit 1
  for update skip locked;

  if v_id is null then
    return null;
  end if;

  update public.enrichment_slots set locked_at = now() where id = v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.merge_contacts(primary_id uuid, secondary_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_secondary_email text;
BEGIN
  SELECT organization_id, email INTO v_org, v_secondary_email FROM contacts WHERE id = secondary_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Secondary contact not found'; END IF;
  IF NOT private.is_org_member(v_org) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF primary_id = secondary_id THEN RAISE EXCEPTION 'Cannot merge a contact with itself'; END IF;

  UPDATE communication_messages SET contact_id = primary_id WHERE contact_id = secondary_id;
  UPDATE meeting_participants SET contact_id = primary_id WHERE contact_id = secondary_id;
  UPDATE behavioral_signals SET contact_id = primary_id WHERE contact_id = secondary_id;

  IF v_secondary_email IS NOT NULL THEN
    UPDATE contacts
    SET secondary_emails = (
      SELECT array_agg(DISTINCT e)
      FROM unnest(coalesce(secondary_emails, '{}') || ARRAY[v_secondary_email]) e
      WHERE e IS NOT NULL AND e <> contacts.email
    )
    WHERE id = primary_id;
  END IF;

  UPDATE contacts
  SET merged_into_contact_id = primary_id,
      updated_at = now()
  WHERE id = secondary_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.unmerge_contact(secondary_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM contacts WHERE id = secondary_id;
  IF v_org IS NULL OR NOT private.is_org_member(v_org) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  UPDATE contacts SET merged_into_contact_id = NULL, enrichment_status = 'pending', updated_at = now()
  WHERE id = secondary_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_fiche_vision_visibility(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_visibility text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if p_entity_type not in ('contact', 'company') or p_visibility not in ('workspace', 'restricted') then
    raise exception 'Invalid visibility';
  end if;
  if not private.is_org_member(p_organization_id) then raise exception 'Not authorized'; end if;

  insert into public.fiche_visions (
    organization_id, entity_type, entity_id, owner_user_id, visibility, relationship_state, created_reason
  ) values (
    p_organization_id, p_entity_type, p_entity_id, auth.uid(), p_visibility, 'active', 'existing'
  )
  on conflict (organization_id, entity_type, entity_id, owner_user_id)
  do update set visibility = excluded.visibility, updated_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.format_person_full_name(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  trimmed text := btrim(coalesce(value, ''));
  comma_pos int;
  before_comma text;
  after_comma text;
  words text[];
begin
  if trimmed = '' then
    return value;
  end if;

  comma_pos := position(',' in trimmed);
  if comma_pos > 0 then
    before_comma := btrim(substr(trimmed, 1, comma_pos - 1));
    after_comma := btrim(substr(trimmed, comma_pos + 1));
    return upper(before_comma) || ', ' || public.format_person_full_name(after_comma);
  end if;

  words := regexp_split_to_array(trimmed, '\s+');
  if array_length(words, 1) = 1 then
    return initcap(words[1]);
  end if;
  return initcap(words[1]) || ' ' || upper(array_to_string(words[2:array_length(words,1)], ' '));
end;
$function$

CREATE OR REPLACE FUNCTION public.share_fiche(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_to_user_id uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
