CREATE OR REPLACE FUNCTION public.super_admin_ai_usage()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result jsonb;
begin
  if not public.is_super_admin_caller() then raise exception 'forbidden'; end if;
  with base as (select * from public.ai_usage_events where fn is not null),
  period as (select p.label, p.since from (values
    ('day',now()-interval '1 day'),('week',now()-interval '7 days'),('month',now()-interval '30 days'),
    ('year',now()-interval '365 days'),('all',timestamptz '1970-01-01')) as p(label,since)),
  totals as (select period.label, count(base.id) calls, coalesce(sum(base.total_tokens),0) tokens, coalesce(sum(base.estimated_cost_usd),0) cost
    from period left join base on base.created_at >= period.since group by period.label),
  agg_fn as (select fn, count(*) calls, coalesce(sum(total_tokens),0) tokens, coalesce(sum(estimated_cost_usd),0) cost
    from base where created_at >= now()-interval '30 days' group by fn order by cost desc),
  agg_model as (select model, count(*) calls, coalesce(sum(total_tokens),0) tokens, coalesce(sum(estimated_cost_usd),0) cost
    from base where created_at >= now()-interval '30 days' group by model order by cost desc),
  agg_day as (select to_char(date_trunc('day',created_at),'YYYY-MM-DD') as d, count(*) calls, coalesce(sum(total_tokens),0) tokens, coalesce(sum(estimated_cost_usd),0) cost
    from base where created_at >= now()-interval '30 days' group by 1 order by 1),
  agg_user as (select b.user_id, coalesce(pr.full_name,'—') full_name, count(*) calls, coalesce(sum(b.total_tokens),0) tokens, coalesce(sum(b.estimated_cost_usd),0) cost
    from base b left join public.profiles pr on pr.id=b.user_id where b.created_at >= now()-interval '30 days' group by b.user_id, pr.full_name order by cost desc limit 20)
  select jsonb_build_object(
    'generated_at', now(),
    'totals', (select jsonb_object_agg(label, jsonb_build_object('calls',calls,'tokens',tokens,'cost',cost)) from totals),
    'by_function', coalesce((select jsonb_agg(jsonb_build_object('fn',fn,'calls',calls,'tokens',tokens,'cost',cost)) from agg_fn),'[]'),
    'by_model', coalesce((select jsonb_agg(jsonb_build_object('model',model,'calls',calls,'tokens',tokens,'cost',cost)) from agg_model),'[]'),
    'by_day', coalesce((select jsonb_agg(jsonb_build_object('day',d,'calls',calls,'tokens',tokens,'cost',cost)) from agg_day),'[]'),
    'by_user', coalesce((select jsonb_agg(jsonb_build_object('user_id',user_id,'full_name',full_name,'calls',calls,'tokens',tokens,'cost',cost)) from agg_user),'[]')
  ) into result;
  return result;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_delete_user(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid := auth.uid();
  v_orgs_deleted int;
  v_email text;
begin
  if not public.is_super_admin_caller() then raise exception 'forbidden'; end if;
  if p_user_id is null then raise exception 'Utilisateur cible manquant.'; end if;
  if p_user_id = v_caller then raise exception 'Impossible de supprimer votre propre compte.'; end if;
  if exists (select 1 from public.profiles where id = p_user_id and is_super_admin = true) then
    raise exception 'Impossible de supprimer un super administrateur (retire d''abord ce rôle).';
  end if;

  select email into v_email from auth.users where id = p_user_id;
  if v_email is null then raise exception 'Utilisateur introuvable.'; end if;

  with target_orgs as (
    select distinct m.organization_id
    from public.memberships m
    where m.user_id = p_user_id
      and (m.role = 'owner'
        or (select count(*) from public.memberships m2 where m2.organization_id = m.organization_id) = 1)
  ), del_orgs as (
    delete from public.organizations o using target_orgs t where o.id = t.organization_id returning o.id
  )
  select count(*) into v_orgs_deleted from del_orgs;

  delete from public.memberships where user_id = p_user_id;
  delete from auth.users where id = p_user_id;

  return jsonb_build_object('deleted_email', v_email, 'organizations_deleted', v_orgs_deleted);
end; $function$

CREATE OR REPLACE FUNCTION public.accept_my_organization_invitations()
 RETURNS TABLE(organization_name text, inviter_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_email text;
  v_invitation public.organization_invitations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_plan_limit integer;
  v_member_count integer;
  v_unlimited boolean;
  v_org_name text;
  v_inviter_name text;
begin
  select lower(email) into v_email from auth.users where id = auth.uid();
  if v_email is null then return; end if;

  for v_invitation in
    select * from public.organization_invitations
    where email = v_email and status = 'pending' and expires_at > now()
    order by created_at
  loop
    select * into v_subscription from public.subscriptions
    where organization_id = v_invitation.organization_id
    order by created_at desc limit 1;
    select max_licenses into v_plan_limit
    from public.subscription_plans
    where id = coalesce(v_subscription.plan_id, 'free');
    select count(*) into v_member_count from public.memberships
    where organization_id = v_invitation.organization_id;
    v_unlimited := coalesce(v_plan_limit, 1) < 0;

    if v_unlimited or v_member_count < least(
      greatest(coalesce(v_subscription.seat_quantity, 1), 1),
      greatest(coalesce(v_plan_limit, 1), 1)
    ) then
      insert into public.memberships (organization_id, user_id, role)
      values (v_invitation.organization_id, auth.uid(), v_invitation.role)
      on conflict (organization_id, user_id) do update set role = excluded.role;

      update public.organization_invitations
      set status = 'accepted', accepted_at = now(), updated_at = now()
      where id = v_invitation.id;

      insert into public.audit_logs (
        organization_id, actor_user_id, action, target_table, target_id, metadata
      ) values (
        v_invitation.organization_id, auth.uid(), 'team_invitation_accepted',
        'memberships', auth.uid(), jsonb_build_object('email', v_email, 'role', v_invitation.role)
      );

      select o.name into v_org_name from public.organizations o where o.id = v_invitation.organization_id;
      select p.full_name into v_inviter_name from public.profiles p where p.id = v_invitation.invited_by;
      organization_name := coalesce(v_org_name, 'l’équipe');
      inviter_name := v_inviter_name;
      return next;
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_user_access(target_user uuid, access_type text, paid_plan text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_organization_id uuid;
  v_subscription_id uuid;
  v_plan_id text;
  v_amount integer;
begin
  if not exists (
    select 1 from public.super_admins sa where sa.user_id = auth.uid()
  ) then
    raise exception 'not authorized' using errcode = '42501';
  end if;

  if access_type not in ('free', 'paid', 'test') then
    raise exception 'Type d''abonnement invalide';
  end if;

  if not exists (select 1 from auth.users u where u.id = target_user and u.deleted_at is null) then
    raise exception 'Utilisateur introuvable';
  end if;

  select m.organization_id
  into v_organization_id
  from public.memberships m
  where m.user_id = target_user
  order by (m.role = 'owner') desc, m.created_at desc
  limit 1;

  if v_organization_id is null then
    raise exception 'Aucun workspace associé à cet utilisateur';
  end if;

  v_plan_id := case
    when access_type = 'free' then 'free'
    when access_type = 'test' then 'tester'
    else lower(coalesce(nullif(paid_plan, ''), 'pro'))
  end;

  if access_type = 'paid' and v_plan_id not in ('solo', 'pro', 'business') then
    raise exception 'Le plan payant doit être Solo, Pro ou Business';
  end if;

  select sp.price_monthly
  into v_amount
  from public.subscription_plans sp
  where sp.id = v_plan_id
    and (sp.is_active or sp.id = 'tester');

  if not found then
    raise exception 'Plan introuvable ou inactif';
  end if;

  perform set_config('app.subscription_changed_by', auth.uid()::text, true);
  perform set_config('app.subscription_target_user', target_user::text, true);
  perform set_config('app.subscription_change_source', 'super_admin', true);
  perform set_config('app.subscription_change_reason', 'Abonnement programmé depuis la console Super Admin', true);

  select s.id
  into v_subscription_id
  from public.subscriptions s
  where s.organization_id = v_organization_id
  order by
    (s.status in ('active', 'trialing', 'past_due')) desc,
    s.updated_at desc
  limit 1;

  if v_subscription_id is null then
    insert into public.subscriptions (
      organization_id,
      plan_id,
      status,
      billing_cycle,
      amount_per_period,
      started_at,
      current_period_start,
      current_period_end
    ) values (
      v_organization_id,
      v_plan_id,
      'active',
      'monthly',
      case when access_type = 'paid' then coalesce(v_amount, 0) else 0 end,
      now(),
      now(),
      now() + interval '1 month'
    );
  else
    update public.subscriptions
    set
      plan_id = v_plan_id,
      status = 'active',
      billing_cycle = 'monthly',
      amount_per_period = case when access_type = 'paid' then coalesce(v_amount, 0) else 0 end,
      canceled_at = null,
      current_period_start = case
        when plan_id is distinct from v_plan_id then now()
        else current_period_start
      end,
      current_period_end = case
        when plan_id is distinct from v_plan_id then now() + interval '1 month'
        else current_period_end
      end,
      updated_at = now()
    where id = v_subscription_id
      and (
        plan_id is distinct from v_plan_id
        or status is distinct from 'active'
        or billing_cycle is distinct from 'monthly'
        or amount_per_period is distinct from case when access_type = 'paid' then coalesce(v_amount, 0) else 0 end
      );
  end if;

  update public.profiles
  set
    subscription_override = v_plan_id,
    updated_at = now()
  where id = target_user;

  insert into public.audit_logs (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  ) values (
    v_organization_id,
    auth.uid(),
    'admin_subscription_programmed',
    'profiles',
    target_user,
    jsonb_build_object(
      'access_type', access_type,
      'plan_id', v_plan_id,
      'subscription_id', v_subscription_id
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_fiche_vision_grant(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_grantee_user_id uuid, p_allowed boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_vision_id uuid;
begin
  if p_entity_type not in ('contact', 'company') or not private.is_org_member(p_organization_id) then
    raise exception 'Not authorized';
  end if;
  if not exists (
    select 1 from public.memberships member
    where member.organization_id = p_organization_id and member.user_id = p_grantee_user_id
  ) then raise exception 'Target user is not a member of this organization'; end if;

  insert into public.fiche_visions (
    organization_id, entity_type, entity_id, owner_user_id, visibility, relationship_state, created_reason
  ) values (
    p_organization_id, p_entity_type, p_entity_id, auth.uid(), 'restricted', 'active', 'existing'
  )
  on conflict (organization_id, entity_type, entity_id, owner_user_id)
  do update set visibility = 'restricted', updated_at = now()
  returning id into v_vision_id;

  if p_allowed then
    insert into public.fiche_vision_grants (vision_id, grantee_user_id, granted_by, reason, revoked_at)
    values (v_vision_id, p_grantee_user_id, auth.uid(), 'manual', null)
    on conflict (vision_id, grantee_user_id)
    do update set revoked_at = null, granted_at = now(), granted_by = auth.uid(), reason = 'manual';
  else
    update public.fiche_vision_grants
    set revoked_at = now()
    where vision_id = v_vision_id and grantee_user_id = p_grantee_user_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.handover_fiches(p_organization_id uuid, p_entity_type text, p_entity_ids uuid[], p_to_user_id uuid, p_scope text DEFAULT 'entity_only'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_entity_id uuid;
  v_contact record;
  v_from_user_id uuid := auth.uid();
  v_current_owner uuid;
  v_sender_vision_id uuid;
  v_entities integer := 0;
  v_people integer := 0;
  v_skipped_people integer := 0;
begin
  if v_from_user_id is null or not private.is_org_member(p_organization_id) then
    raise exception 'Not authorized';
  end if;
  if p_entity_type not in ('contact', 'company') or p_scope not in ('entity_only', 'account_and_people') then
    raise exception 'Invalid handover';
  end if;
  if p_entity_type = 'contact' and p_scope <> 'entity_only' then raise exception 'Invalid contact scope'; end if;
  if p_to_user_id = v_from_user_id then raise exception 'Target user already owns this vision'; end if;
  if not exists (
    select 1 from public.memberships member
    where member.organization_id = p_organization_id and member.user_id = p_to_user_id
  ) then raise exception 'Target user is not a member of this organization'; end if;

  foreach v_entity_id in array coalesce(p_entity_ids, '{}'::uuid[]) loop
    if p_entity_type = 'contact' then
      select coalesce(settings.primary_owner_user_id, contact.owner_user_id)
      into v_current_owner
      from public.contacts contact
      left join public.person_settings settings
        on settings.organization_id = contact.organization_id and settings.contact_id = contact.id
      where contact.organization_id = p_organization_id
        and contact.id = v_entity_id
        and contact.merged_into_contact_id is null
      for update of contact;

      if not found then raise exception 'Contact not found'; end if;
      if v_current_owner is not null and v_current_owner <> v_from_user_id then
        raise exception 'Only the current owner can hand over this contact';
      end if;

      insert into public.fiche_visions (
        organization_id, entity_type, entity_id, owner_user_id, relationship_state, created_reason
      ) values (p_organization_id, 'contact', v_entity_id, v_from_user_id, 'active', 'existing')
      on conflict (organization_id, entity_type, entity_id, owner_user_id)
      do update set relationship_state = 'active', updated_at = now()
      returning id into v_sender_vision_id;

      insert into public.fiche_visions (
        organization_id, entity_type, entity_id, owner_user_id,
        visibility, relationship_state, created_reason
      ) values (
        p_organization_id, 'contact', v_entity_id, p_to_user_id,
        'restricted', 'relationship_to_build', 'handover'
      ) on conflict (organization_id, entity_type, entity_id, owner_user_id) do nothing;

      insert into public.fiche_vision_grants (vision_id, grantee_user_id, granted_by, reason, revoked_at)
      values (v_sender_vision_id, p_to_user_id, v_from_user_id, 'handover', null)
      on conflict (vision_id, grantee_user_id)
      do update set revoked_at = null, granted_at = now(), granted_by = v_from_user_id, reason = 'handover';

      update public.contacts set owner_user_id = p_to_user_id, updated_at = now() where id = v_entity_id;
      insert into public.person_settings (
        organization_id, contact_id, primary_owner_user_id, updated_by, updated_at
      ) values (p_organization_id, v_entity_id, p_to_user_id, v_from_user_id, now())
      on conflict (organization_id, contact_id)
      do update set primary_owner_user_id = excluded.primary_owner_user_id, updated_by = excluded.updated_by, updated_at = now();

      insert into public.fiche_handovers (
        organization_id, entity_type, entity_id, from_user_id, to_user_id, scope, note, transferred_by
      ) values (p_organization_id, 'contact', v_entity_id, v_from_user_id, p_to_user_id, 'entity_only', nullif(btrim(p_note), ''), v_from_user_id);
      insert into public.contact_transfers (
        organization_id, contact_id, from_user_id, to_user_id, kept_copy, transferred_by
      ) values (p_organization_id, v_entity_id, v_from_user_id, p_to_user_id, true, v_from_user_id);
      v_entities := v_entities + 1;
    else
      select settings.primary_owner_user_id
      into v_current_owner
      from public.companies company
      left join public.account_settings settings
        on settings.organization_id = company.organization_id and settings.company_id = company.id
      where company.organization_id = p_organization_id and company.id = v_entity_id
      for update of company;

      if not found then raise exception 'Company not found'; end if;
      if v_current_owner is not null and v_current_owner <> v_from_user_id then
        raise exception 'Only the current owner can hand over this company';
      end if;

      insert into public.fiche_visions (
        organization_id, entity_type, entity_id, owner_user_id, relationship_state, created_reason
      ) values (p_organization_id, 'company', v_entity_id, v_from_user_id, 'active', 'existing')
      on conflict (organization_id, entity_type, entity_id, owner_user_id)
      do update set relationship_state = 'active', updated_at = now()
      returning id into v_sender_vision_id;

      insert into public.fiche_visions (
        organization_id, entity_type, entity_id, owner_user_id,
        visibility, relationship_state, created_reason
      ) values (
        p_organization_id, 'company', v_entity_id, p_to_user_id,
        'restricted', 'relationship_to_build', 'handover'
      ) on conflict (organization_id, entity_type, entity_id, owner_user_id) do nothing;

      insert into public.fiche_vision_grants (vision_id, grantee_user_id, granted_by, reason, revoked_at)
      values (v_sender_vision_id, p_to_user_id, v_from_user_id, 'handover', null)
      on conflict (vision_id, grantee_user_id)
      do update set revoked_at = null, granted_at = now(), granted_by = v_from_user_id, reason = 'handover';

      insert into public.account_settings (
        organization_id, company_id, primary_owner_user_id, updated_by, updated_at
      ) values (p_organization_id, v_entity_id, p_to_user_id, v_from_user_id, now())
      on conflict (organization_id, company_id)
      do update set primary_owner_user_id = excluded.primary_owner_user_id, updated_by = excluded.updated_by, updated_at = now();

      insert into public.fiche_handovers (
        organization_id, entity_type, entity_id, from_user_id, to_user_id, scope, note, transferred_by
      ) values (p_organization_id, 'company', v_entity_id, v_from_user_id, p_to_user_id, p_scope, nullif(btrim(p_note), ''), v_from_user_id);
      v_entities := v_entities + 1;

      if p_scope = 'account_and_people' then
        for v_contact in
          select contact.id, coalesce(settings.primary_owner_user_id, contact.owner_user_id) as current_owner
          from public.contacts contact
          left join public.person_settings settings
            on settings.organization_id = contact.organization_id and settings.contact_id = contact.id
          where contact.organization_id = p_organization_id
            and contact.company_id = v_entity_id
            and contact.merged_into_contact_id is null
          for update of contact
        loop
          if v_contact.current_owner is not null and v_contact.current_owner <> v_from_user_id then
            v_skipped_people := v_skipped_people + 1;
            continue;
          end if;

          insert into public.fiche_visions (
            organization_id, entity_type, entity_id, owner_user_id, relationship_state, created_reason
          ) values (p_organization_id, 'contact', v_contact.id, v_from_user_id, 'active', 'existing')
          on conflict (organization_id, entity_type, entity_id, owner_user_id)
          do update set relationship_state = 'active', updated_at = now()
          returning id into v_sender_vision_id;

          insert into public.fiche_visions (
            organization_id, entity_type, entity_id, owner_user_id,
            visibility, relationship_state, created_reason
          ) values (
            p_organization_id, 'contact', v_contact.id, p_to_user_id,
            'restricted', 'relationship_to_build', 'handover'
          ) on conflict (organization_id, entity_type, entity_id, owner_user_id) do nothing;

          insert into public.fiche_vision_grants (vision_id, grantee_user_id, granted_by, reason, revoked_at)
          values (v_sender_vision_id, p_to_user_id, v_from_user_id, 'handover', null)
          on conflict (vision_id, grantee_user_id)
          do update set revoked_at = null, granted_at = now(), granted_by = v_from_user_id, reason = 'handover';

          update public.contacts set owner_user_id = p_to_user_id, updated_at = now() where id = v_contact.id;
          insert into public.person_settings (
            organization_id, contact_id, primary_owner_user_id, updated_by, updated_at
          ) values (p_organization_id, v_contact.id, p_to_user_id, v_from_user_id, now())
          on conflict (organization_id, contact_id)
          do update set primary_owner_user_id = excluded.primary_owner_user_id, updated_by = excluded.updated_by, updated_at = now();

          insert into public.fiche_handovers (
            organization_id, entity_type, entity_id, from_user_id, to_user_id, scope, note, transferred_by
          ) values (p_organization_id, 'contact', v_contact.id, v_from_user_id, p_to_user_id, 'entity_only', nullif(btrim(p_note), ''), v_from_user_id);
          insert into public.contact_transfers (
            organization_id, contact_id, from_user_id, to_user_id, kept_copy, transferred_by
          ) values (p_organization_id, v_contact.id, v_from_user_id, p_to_user_id, true, v_from_user_id);
          v_people := v_people + 1;
        end loop;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'entities', v_entities,
    'people', v_people,
    'skipped_people', v_skipped_people,
    'scope', p_scope
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_account_deletion_request(p_organization_id uuid, p_primary_reason text, p_retention_factor text, p_deletion_scope text, p_details text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_request_id uuid;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if p_organization_id is not null and not private.is_org_member(p_organization_id) then
    raise exception 'not authorized';
  end if;
  if p_primary_reason not in ('not_useful', 'too_expensive', 'missing_features', 'technical_issues', 'privacy', 'other') then
    raise exception 'invalid primary reason';
  end if;
  if p_retention_factor not in ('better_price', 'better_reliability', 'more_features', 'more_support', 'temporary_pause', 'nothing', 'other') then
    raise exception 'invalid retention factor';
  end if;
  if p_deletion_scope not in ('account_and_data', 'workspace_and_data', 'product_data_only', 'not_sure', 'other') then
    raise exception 'invalid deletion scope';
  end if;
  if char_length(trim(coalesce(p_details, ''))) < 20 then
    raise exception 'details must contain at least 20 characters';
  end if;
  if exists (
    select 1 from public.account_deletion_requests
    where user_id = auth.uid() and status in ('pending', 'reviewing', 'confirmed')
  ) then
    raise exception 'an active deletion request already exists';
  end if;

  insert into public.account_deletion_requests (
    user_id, organization_id, primary_reason, retention_factor, deletion_scope, details
  ) values (
    auth.uid(), p_organization_id, p_primary_reason, p_retention_factor, p_deletion_scope, trim(p_details)
  )
  returning id into v_request_id;

  insert into public.audit_logs (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    p_organization_id, auth.uid(), 'account_deletion_requested',
    'account_deletion_requests', v_request_id,
    jsonb_build_object('status', 'pending')
  );

  return v_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_account_deletion_request(p_request_id uuid, p_status text, p_admin_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_request public.account_deletion_requests%rowtype;
begin
  if not public.is_super_admin() then raise exception 'not authorized'; end if;
  if p_status not in ('pending', 'reviewing', 'confirmed', 'completed', 'rejected') then
    raise exception 'invalid status';
  end if;

  select * into v_request from public.account_deletion_requests where id = p_request_id;
  if v_request.id is null then raise exception 'request not found'; end if;

  update public.account_deletion_requests
  set
    status = p_status,
    admin_note = nullif(trim(coalesce(p_admin_note, '')), ''),
    assigned_to = case when p_status in ('reviewing', 'confirmed', 'completed', 'rejected') then auth.uid() else assigned_to end,
    reviewed_at = case when p_status in ('reviewing', 'confirmed', 'rejected') then coalesce(reviewed_at, now()) else reviewed_at end,
    completed_at = case when p_status = 'completed' then now() else null end,
    updated_at = now()
  where id = p_request_id;

  insert into public.audit_logs (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_request.organization_id, auth.uid(), 'account_deletion_request_status_changed',
    'account_deletion_requests', p_request_id,
    jsonb_build_object('from', v_request.status, 'to', p_status, 'admin_note', nullif(trim(coalesce(p_admin_note, '')), ''))
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_user_plan(target_user uuid, new_plan text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare oid uuid;
begin
  if not exists (select 1 from public.super_admins sa where sa.user_id = auth.uid()) then
    raise exception 'not authorized';
  end if;
  select mm.organization_id into oid from public.memberships mm
    where mm.user_id = target_user order by mm.created_at desc limit 1;
  if oid is null then raise exception 'no organization for user'; end if;

  -- reflète aussi l'override par utilisateur (affichage page Abonnement)
  update public.profiles set subscription_override = new_plan where id = target_user;

  if exists (select 1 from public.subscriptions where organization_id = oid) then
    update public.subscriptions
      set plan_id = new_plan, status = 'active', updated_at = now()
      where organization_id = oid;
  else
    insert into public.subscriptions
      (organization_id, plan_id, status, billing_cycle, amount_per_period,
       started_at, current_period_start, current_period_end)
    values
      (oid, new_plan, 'active', 'monthly', 0, now(), now(), now() + interval '30 days');
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_org_logo(p_org uuid, p_logo text)
 RETURNS void
