CREATE OR REPLACE FUNCTION public.admin_set_super_admin(target_user uuid, make_admin boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_was_admin boolean;
  v_organization_id uuid;
begin
  if not exists (
    select 1 from public.super_admins sa where sa.user_id = auth.uid()
  ) then
    raise exception 'not authorized' using errcode = '42501';
  end if;

  if not exists (select 1 from auth.users u where u.id = target_user and u.deleted_at is null) then
    raise exception 'Utilisateur introuvable';
  end if;

  if target_user = auth.uid() and not make_admin then
    raise exception 'Vous ne pouvez pas retirer votre propre rôle Super Admin';
  end if;

  select exists (
    select 1 from public.super_admins sa where sa.user_id = target_user
  ) into v_was_admin;

  if v_was_admin = make_admin then
    return;
  end if;

  if make_admin then
    insert into public.super_admins (user_id, email)
    select u.id, lower(u.email)
    from auth.users u
    where u.id = target_user
    on conflict (user_id) do update set email = excluded.email;

    update public.profiles
    set platform_role = 'super_admin', is_super_admin = true, updated_at = now()
    where id = target_user;
  else
    delete from public.super_admins where user_id = target_user;

    update public.profiles
    set platform_role = 'user', is_super_admin = false, updated_at = now()
    where id = target_user;
  end if;

  select m.organization_id
  into v_organization_id
  from public.memberships m
  where m.user_id = target_user
  order by (m.role = 'owner') desc, m.created_at desc
  limit 1;

  insert into public.audit_logs (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  ) values (
    v_organization_id,
    auth.uid(),
    'admin_platform_role_changed',
    'profiles',
    target_user,
    jsonb_build_object(
      'previous_role', case when v_was_admin then 'super_admin' else 'user' end,
      'new_role', case when make_admin then 'super_admin' else 'user' end
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.store_oauth_tokens_server(p_organization_id uuid, p_connector_id uuid, p_provider_account_id text, p_access_token text, p_refresh_token text, p_expires_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'extensions', 'pg_temp'
AS $function$
declare
  encryption_key text;
  encrypted_access text;
  encrypted_refresh text;
begin
  select decrypted_secret into encryption_key
  from vault.decrypted_secrets
  where name = 'tohu_oauth_token_encryption_key'
  limit 1;

  if encryption_key is null then
    raise exception 'OAuth encryption key unavailable';
  end if;

  encrypted_access := encode(extensions.pgp_sym_encrypt(p_access_token, encryption_key), 'base64');
  encrypted_refresh := case
    when p_refresh_token is null or p_refresh_token = '' then null
    else encode(extensions.pgp_sym_encrypt(p_refresh_token, encryption_key), 'base64')
  end;

  insert into public.oauth_accounts (
    organization_id, connector_id, provider_account_id,
    encrypted_access_token, encrypted_refresh_token, expires_at, updated_at
  ) values (
    p_organization_id, p_connector_id, p_provider_account_id,
    encrypted_access, encrypted_refresh, p_expires_at, now()
  )
  on conflict (connector_id) do update set
    organization_id = excluded.organization_id,
    provider_account_id = excluded.provider_account_id,
    encrypted_access_token = excluded.encrypted_access_token,
    encrypted_refresh_token = coalesce(excluded.encrypted_refresh_token, public.oauth_accounts.encrypted_refresh_token),
    expires_at = excluded.expires_at,
    updated_at = now();
end;
$function$

